    def test_replay_and_late_event(self) -> None:
        """Use case: Replay and reorder callbacks. Expected result: one terminal call and deduplicated events."""
        from bloomerp.communication.builtins.voip.controller import reconcile_call
        from bloomerp.communication.builtins.voip.definition import VoIPCallData

        # 1. Reconcile a completed call twice, then receive a late ringing event.
        self.prepare_voip()
        completed = VoIPCallData(
            "CA" + "5" * 32,
            "",
            self.number.number,
            self.identity.address,
            "outbound",
            "completed",
            timezone.now(),
            timezone.now(),
            42,
        )
        with patch(
            "bloomerp.communication.builtins.voip.controller.notify_conversation"
        ):
            first = reconcile_call(self.connection, completed, "done")
            reconcile_call(self.connection, completed, "done")
            reconcile_call(
                self.connection,
                VoIPCallData(
                    completed.external_id,
                    "",
                    completed.from_address,
                    completed.to_address,
                    "outbound",
                    "ringing",
                    None,
                    None,
                    0,
                ),
                "ringing",
            )
        # 2. Terminal state survives late events and history survives disconnect.
        first.refresh_from_db()
        self.assertEqual(first.status, "completed")
        self.assertEqual(first.duration, 42)
        self.assertEqual(first.events.count(), 2)
        self.assertEqual(PhoneCall.objects.count(), 1)
        self.number.is_active = False
        self.number.save()
        from bloomerp.communication.builtins.voip.access import VoIPAccessManager

        self.assertTrue(
            VoIPAccessManager(self.normal_user).get_calls().filter(pk=first.pk).exists()
        )
        with self.assertRaises(ProtectedError):
            self.number.delete()

    def test_line_revocation_blocks_call(self) -> None:
        """Use case: Revoke a line assignment. Expected result: existing chat membership cannot place calls."""
        from bloomerp.communication.builtins.voip.controller import VoIPController

        # 1. Remove authorization without removing historical membership.
        self.prepare_voip()
        self.number.assigned_users.clear()
        # 2. Enforce current line access at the service boundary.
        with self.assertRaises(PermissionDenied):
            VoIPController(self.normal_user).prepare_call(self.chat.pk, "request")
